head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > showHeaderFilter]<br/>GridView 컴포넌트에 HeaderFilter 를 표시하거나 숨깁니다.",
    "validation" : [
        "headerFilter=true 인 경우에만 동작합니다.",
        "Column 의 useFilter 속성과 GridView 의 useFilterList 속성, 그리고 해당 속성과 연관된 속성은 동작하지 않습니다.",
        "flag(필수) 파라미터로 HeaderFilter 의 표시 여부를 true/false 로 설정합니다.",
        "flag(필수) 파라미터를 true 로 설정 시 HeaderFilter 를 Header 의 마지막 Row 로 표시합니다.",
        "flag(필수) 파라미터를 false 로 설정 시 HeaderFilter 를 Header 에서 숨깁니다.",
        "HeaderFilter 기능은 동적으로 생성이 불가능하며 렌더링 시 생성 여부를 결정한 후 표시 여부만 동적으로 처리합니다.",
        "headerFilter=false 이면 HeaderFilter 기능이 생성되지 않아 defaultShowHeaderFilter 속성 및 showHeaderFilter() 메소드가 동작하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // con_headerFilter : '' 미설정(기본 false) / 'true' / 'false'
    let vHeaderFilter = con_headerFilter.getText();

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    let lblHf = (vHeaderFilter === '' ? '(미설정=기본 false)' : vHeaderFilter);
    $c.gcm.createLabel('label="[전제] headerFilter=' + lblHf + ' 로 그리드 생성, 필터 행은 초기 숨김(display:none)으로 시작 (defaultShowHeaderFilter 미설정)\n[절차] par_flag(true 또는 false) 선택 후 showHeaderFilter 버튼 클릭\n[확인] 필터 행(filter tr)의 표시/숨김 여부로 확인. headerFilter=false 또는 미설정이면 필터 행이 없어 showHeaderFilter(true) 를 호출해도 항상 숨김으로 표시됨"', '', 'label1');

    // dataList 생성 (4행, col1~col4)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // headerFilter 속성을 con 값에 따라 적용한 커스텀 gridView 생성
    //  (createBasicGridView 는 filterColumn/headerFilter 구성 불가 → 인라인 구성)
    await scwin.createHeaderFilterGridView(vHeaderFilter);
}



// headerFilter 필터 행(filterColumn)을 포함한 gridView 동적 생성
scwin.createHeaderFilterGridView = async function (vHeaderFilter) {
    let grp_comp = $c.gcm.getTestGroup('');
    let ns = $c.gcm.strNameSpace;

    // headerFilter 속성 : 미설정('') 이면 속성 미추가(기본 false → 필터 기능 미생성)
    let hfAttr = '';
    if (vHeaderFilter === 'true') {
        hfAttr = ' headerFilter="true"';
    } else if (vHeaderFilter === 'false') {
        hfAttr = ' headerFilter="false"';
    }

    let s = '';
    s += '<w2:gridView ' + ns + hfAttr + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:500px;height:300px;">';
    s += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="120" style="" inputType="text" id="column1" value="col1"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column2" value="col2"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column3" value="col3"></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="column4" value="col4"></w2:column>';
    s += '</w2:row>';
    s += '<w2:row style="" id="rowFilter">';
    s += '<w2:filterColumn width="120" style="" id="filterColumn1" value=""></w2:filterColumn>';
    s += '<w2:filterColumn width="120" style="" id="filterColumn2" value=""></w2:filterColumn>';
    s += '<w2:filterColumn width="120" style="" id="filterColumn3" value=""></w2:filterColumn>';
    s += '<w2:filterColumn width="*" style="" id="filterColumn4" value=""></w2:filterColumn>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="120" style="" inputType="text" id="col1" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col2" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col3" value=""></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="col4" value=""></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// showHeaderFilter(flag) 호출 후 필터 행(filter tr)의 표시/숨김 여부를 통일된 형식으로 출력
scwin.btn_showHeaderFilter_onclick = function () {
    let flag = par_flag.getText() === 'true'; // 필수 param : true / false

    target1.showHeaderFilter(flag);

    let filterTr = document.querySelector("[id*='target1_head_table'] tr.w2grid_header_filter");
    let shown = !!(filterTr && filterTr.style.display !== 'none');
    wf_body_bottom.getObj("scwin").setReturnValue("showHeaderFilter(" + flag + ") -> 필터 행 표시 여부 : " + (shown ? '표시' : '숨김'));
}
